                <input
                    id="chatbot-email"
                    type="email"
                    autocomplete="email"
                    required>

                <label for="chatbot-phone">
                    Tel\xE9fono
                </label>

                <input
                    id="chatbot-phone"
                    type="tel"
                    autocomplete="tel"
                    required>

                <button
                    type="submit"
                    id="chatbot-lead-submit">
                    Solicitar informaci\xF3n
                </button>

            </form>
        </section>
